rows=[[6]*29 for _ in range(8)]; vals=['6 9 9 9 9 9 9 9 9 9 9 9 9 6 9 9 9 9 9 9 6 6 6 9 9 9 9 9 6','6 9 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 9 6','6 9 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 9 6','6 9 9 9 9 9 9 6 9 9 9 6 9 6 9 6 9 9 9 9 9 6 9 9 6 6 9 9 6','6 9 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 9 6','6 9 6 9 9 9 9 9 9 9 9 9 6 6 6 9 9 6 9 9 9 9 9 6 9 9 9 9 6'];
for i,line in enumerate(vals,2): rows[i]=list(map(int,line.split()))
# each row/col with marker count >=2 fill between extreme
for r in range(8):
 cs=[c for c,x in enumerate(rows[r]) if x==9]
 if len(cs)>=2:
  for c in range(min(cs),max(cs)+1):
   if rows[r][c]==6: rows[r][c]=2
for c in range(29):
 rs=[r for r in range(8) if rows[r][c]==9]
 if len(rs)>=2:
  for r in range(min(rs),max(rs)+1):
   if rows[r][c]==6: rows[r][c]=2
print(rows)

g=[[6]*29 for _ in range(8)]; lines=['6 9 9 9 9 9 9 9 9 9 9 9 9 6 9 9 9 9 9 9 6 6 6 9 9 9 9 9 6','6 9 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 9 6','6 9 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 9 6','6 9 9 9 9 9 9 6 9 9 9 6 9 6 9 6 9 9 9 9 9 6 9 9 6 6 9 9 6','6 9 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 6 9 6','6 9 6 9 9 9 9 9 9 9 9 9 6 6 6 9 9 6 9 9 9 9 9 6 9 9 9 9 6'];
for r,line in enumerate(lines,2):g[r]=list(map(int,line.split()))
# components 4 neighbors
lab={}; k=0
for r in range(8):
 for c in range(29):
  if g[r][c]==9 and (r,c) not in lab:
   k+=1; stack=[(r,c)];lab[r,c]=k
   while stack:
    a,b=stack.pop()
    for q in [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]:
     if 0<=q[0]<8 and 0<=q[1]<29 and g[q[0]][q[1]]==9 and q not in lab:lab[q]=k;stack.append(q)
print(k,[(z,sum(1 for v in lab.values() if v==z)) for z in range(1,k+1)])
# fill between distinct component endpoint pairs same row/col
out=[x[:] for x in g]
for r in range(8):
 for c1 in range(29):
  for c2 in range(c1+1,29):
   if g[r][c1]==g[r][c2]==9 and lab[r,c1]!=lab[r,c2]:
    for c in range(c1+1,c2):
     if g[r][c]==6:out[r][c]=2
for c in range(29):
 for r1 in range(8):
  for r2 in range(r1+1,8):
   if g[r1][c]==g[r2][c]==9 and lab[r1,c]!=lab[r2,c]:
    for r in range(r1+1,r2):
     if g[r][c]==6:out[r][c]=2
print(out)
